scripts.hiring-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'hiring-store',
  description:
    "Read and update the hiring desk: roles.json (open roles and their requirements), candidates.json (each candidate's stage) and feedback.json (interview scorecards and notes). action:'status' for every pipeline, the interviews coming up and the scorecards still missing; 'add_role' to open or update a role; 'add_candidate' to add a candidate (an existing name in that role is updated, never duplicated); 'move' to change a stage or book an interview; 'feedback' to record a scorecard; 'list' for every candidate.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add_role', 'add_candidate', 'move', 'feedback', or 'list'.",
      required: true,
    },
    title: { type: 'string', description: "For add_role: the role's title, e.g. 'Barista'." },
    requirements: {
      type: 'string',
      description: "For add_role: the job-related requirements interviewers rate, separated by commas, e.g. 'Coffee and milk skills, Warm customer service'.",
    },
    openings: { type: 'number', description: 'For add_role: how many people the role will hire.' },
    manager: { type: 'string', description: 'For add_role: the hiring manager.' },
    pay: { type: 'string', description: "For add_role: pay as the business states it, e.g. '$19-21 an hour plus tips'." },
    roleStatus: { type: 'string', description: 'For add_role: open, paused, filled, or closed.' },
    role: { type: 'string', description: "Role id (e.g. 'role-1') or title." },
    candidate: {
      type: 'string',
      description: "Candidate id (e.g. 'cand-3') or name; a first name is enough when it is unique.",
    },
    name: { type: 'string', description: "For add_candidate: the candidate's full name." },
    source: { type: 'string', description: 'For add_candidate: where they came from, e.g. referral or job board.' },
    status: { type: 'string', description: 'The stage: sourced, screen, interview, offer, hired, or closed.' },
    interviewOn: {
      type: 'string',
      description: "The interview date, YYYY-MM-DD or a weekday such as 'thursday'.",
    },
    interviewTime: { type: 'string', description: "The interview time as said, e.g. '2:30 pm'." },
    interviewer: { type: 'string', description: 'Who will interview.' },
    by: { type: 'string', description: 'For feedback: who did the interview.' },
    ratings: {
      type: 'string',
      description: "For feedback: 1 to 4 per requirement, e.g. 'Coffee and milk skills 3, Warm customer service 4'.",
    },
    note: { type: 'string', description: 'What happened, in job-related terms.' },
    withinDays: { type: 'number', description: 'How many days ahead count as coming up (default 7).' },
  },
  outputs: {
    openRoles: { type: 'number', description: 'Roles open or paused.' },
    inPipeline: { type: 'number', description: 'Candidates not yet hired or closed.' },
    interviewsSoon: { type: 'number', description: 'Interviews booked within the window.' },
    summary: { type: 'string', description: 'What changed, then the desk picture or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── hiring-rules-start ──
// Pure derivations: dates in local calendar days, record matching, the
// protected-characteristics guard, scorecard parsing and the desk picture the
// crew reads. Kept self-contained between these sentinels so tests execute the
// shipped bytes.
var DAY_MS = 86400000;
var WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
var MONTH_KEYS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function noon(day) {
  return new Date(String(day).slice(0, 10) + 'T12:00:00');
}
function addDays(day, n) {
  var d = noon(day);
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function addMonths(day, months) {
  var d = noon(day);
  var date = d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() + months);
  // The 31st rolls to the last day of a shorter month, not into the next one.
  d.setDate(Math.min(date, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
  return localDay(d.getTime());
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function dayName(day) {
  return WEEKDAYS[noon(day).getDay()];
}
function parseDay(text, nowMs, direction) {
  var raw = String(text == null ? '' : text).trim().toLowerCase().replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!raw) return null;
  var iso = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:t.*)?$/);
  if (iso) return iso[1] + '-' + pad(Number(iso[2])) + '-' + pad(Number(iso[3]));
  var today = localDay(nowMs);
  if (raw === 'today' || raw === 'now') return today;
  if (raw === 'tomorrow') return addDays(today, 1);
  if (raw === 'yesterday') return addDays(today, -1);
  var rel = raw.match(/^(?:in )?(\d{1,3}) (day|days|week|weeks)( ago| from now)?$/);
  if (rel) {
    var n = Number(rel[1]) * (rel[2].charAt(0) === 'w' ? 7 : 1);
    return addDays(today, rel[3] === ' ago' ? -n : n);
  }
  var wd = raw.match(/^(this |next |last |on |coming )?(sun|mon|tue|wed|thu|fri|sat)[a-z]*$/);
  if (wd) {
    var target = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'].indexOf(wd[2]);
    var now = noon(today).getDay();
    if (direction === 'past' || wd[1] === 'last ') {
      var back = (now - target + 7) % 7;
      return addDays(today, -(wd[1] === 'last ' && back === 0 ? 7 : back));
    }
    if (wd[1] === 'this ') return addDays(today, (target - now + 7) % 7);
    return addDays(today, ((target - now + 6) % 7) + 1);
  }
  var md = raw.match(/^(?:[a-z]+day )?([a-z]{3,9}) (\d{1,2})(?:st|nd|rd|th)?(?: (\d{4}))?$/);
  var dm = raw.match(/^(?:[a-z]+day )?(\d{1,2})(?:st|nd|rd|th)? (?:of )?([a-z]{3,9})(?: (\d{4}))?$/);
  var parts = md ? { month: md[1], date: md[2], year: md[3] } : dm ? { month: dm[2], date: dm[1], year: dm[3] } : null;
  if (parts) {
    var m = MONTH_KEYS.indexOf(parts.month.slice(0, 3));
    if (m < 0) return null;
    var date = Number(parts.date);
    if (date < 1 || date > 31) return null;
    if (parts.year) return parts.year + '-' + pad(m + 1) + '-' + pad(date);
    var year = noon(today).getFullYear();
    var guess = year + '-' + pad(m + 1) + '-' + pad(date);
    var d = daysLeft(guess, nowMs);
    if (direction === 'past' && d > 0) guess = year - 1 + guess.slice(4);
    if (direction !== 'past' && d < 0) guess = year + 1 + guess.slice(4);
    return guess;
  }
  return null;
}
function matches(records, text, labelOf) {
  var wanted = String(text == null ? '' : text).trim().toLowerCase().replace(/['\u2019]s\b/g, '').replace(/\s+/g, ' ');
  if (!wanted) return [];
  var tiers = [
    function (r) { return String(r.id).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) === 0; },
    function (r) { return (' ' + labelOf(r).toLowerCase() + ' ').indexOf(' ' + wanted + ' ') >= 0; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) >= 0; },
    function (r) { var l = labelOf(r).toLowerCase(); return l.length >= 3 && wanted.indexOf(l) >= 0; },
  ];
  for (var i = 0; i < tiers.length; i++) {
    var hit = records.filter(tiers[i]);
    if (hit.length) return hit;
  }
  return [];
}
function describe(records, labelOf) {
  return records.map(function (r) { return r.id + ' ' + labelOf(r); }).join(', ');
}
function splitList(text) {
  var raw = String(text == null ? '' : text).trim();
  if (/^\[/.test(raw)) {
    try {
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map(function (s) { return String(s).trim(); }).filter(Boolean);
    } catch (e) {
      // Not JSON after all; split it as text.
    }
  }
  return raw
    .split(/\s*[,;\n]+\s*/)
    .map(function (s) { return s.replace(/^(and|or|plus)\s+/i, '').replace(/[.\s]+$/, '').trim(); })
    .filter(Boolean);
}
var STAGES = ['sourced', 'screen', 'interview', 'offer', 'hired', 'closed'];
var ROLE_STATUSES = ['open', 'paused', 'filled', 'closed'];
var STAGE_WORDS = {
  sourcing: 'sourced', new: 'sourced', applied: 'sourced', screening: 'screen', 'phone screen': 'screen',
  interviewing: 'interview', interviews: 'interview', offered: 'offer', 'offer out': 'offer', hire: 'hired',
  rejected: 'closed', reject: 'closed', declined: 'closed', withdrew: 'closed', withdrawn: 'closed',
  'not moving forward': 'closed', close: 'closed',
};
// A requirement or a rating may never name a protected characteristic.
var PROTECTED = /\b(age|aged|ages|young|younger|youthful|older|elderly|race|racial|ethnic|ethnicity|skin colou?r|religion|religious|gender|sex|sexual orientation|male|female|pregnant|pregnancy|maternity|disabled|disability|disabilities|national origin|nationality|native speaker|marital|married|genetic|veteran status)\b/i;
var STOP = ['and', 'the', 'with', 'for', 'skill', 'skills', 'good', 'great', 'strong', 'very', 'their'];

function protectedTerm(text) {
  var m = String(text == null ? '' : text).match(PROTECTED);
  return m ? m[1].toLowerCase() : null;
}
function protectedMessage(term) {
  return (
    "Hiring Desk never rates or screens on '" + term + "'. Requirements and ratings cover the job only " +
    '(skills, experience, availability, how someone works); age, race, religion, sex, pregnancy, disability, ' +
    'national origin and other protected traits stay out of hiring.'
  );
}
function stageOf(text) {
  var raw = String(text == null ? '' : text).trim().toLowerCase();
  return STAGE_WORDS[raw] || raw;
}
function words(text) {
  return (String(text == null ? '' : text).toLowerCase().match(/[a-z0-9]+/g) || [])
    .filter(function (w) { return w.length >= 3 && STOP.indexOf(w) < 0; })
    .map(function (w) { return w.length > 4 ? w.replace(/ies$/, 'y').replace(/s$/, '') : w; });
}
function matchRequirement(label, requirements) {
  var want = words(label);
  var best = null;
  var score = 0;
  (requirements || []).forEach(function (req) {
    var have = words(req);
    var hits = want.filter(function (w) {
      return have.some(function (h) { return h === w || (w.length >= 4 && h.indexOf(w) === 0) || (h.length >= 4 && w.indexOf(h) === 0); });
    }).length;
    if (hits > score) {
      best = req;
      score = hits;
    }
  });
  return best;
}
function parseRatings(text, requirements) {
  var out = { ratings: {}, unmatched: [], problems: [] };
  var re = /([a-z][a-z '&\/-]*?)\s*[:=(-]?\s*(\d+(?:\.\d+)?)\s*(?:\/\s*\d+|out of \d+)?\)?/gi;
  var m;
  while ((m = re.exec(String(text == null ? '' : text)))) {
    var label = m[1].replace(/^\s*(and|plus|also|then)\s+/i, '').replace(/\s+(is|was|got|scored|a|an)$/i, '').trim();
    if (!label) continue;
    var term = protectedTerm(label);
    if (term) throw new Error(protectedMessage(term));
    var score = Number(m[2]);
    if (!(score >= 1 && score <= 4) || Math.round(score) !== score) {
      out.problems.push(label + ' ' + m[2] + ' is not a whole rating from 1 to 4');
      continue;
    }
    var req = matchRequirement(label, requirements);
    var key = req || label.charAt(0).toUpperCase() + label.slice(1);
    if (!req && out.unmatched.indexOf(key) < 0) out.unmatched.push(key);
    out.ratings[key] = score;
  }
  return out;
}
function cardsFor(candidate, events) {
  return events.filter(function (e) { return e.kind === 'scorecard' && e.data && e.data.candidateId === candidate.id; });
}
function averages(candidate, events) {
  var sums = {};
  cardsFor(candidate, events).forEach(function (e) {
    Object.keys(e.data.ratings || {}).forEach(function (k) {
      sums[k] = sums[k] || { total: 0, count: 0 };
      sums[k].total += Number(e.data.ratings[k]);
      sums[k].count += 1;
    });
  });
  var out = {};
  Object.keys(sums).forEach(function (k) { out[k] = Math.round((sums[k].total / sums[k].count) * 10) / 10; });
  return out;
}
function interviewText(c) {
  var f = c.fields || {};
  return f.interviewAt
    ? dayName(f.interviewAt) + ' ' + f.interviewAt + (f.interviewTime ? ' at ' + f.interviewTime : '') + (f.interviewer ? ' with ' + f.interviewer : '')
    : 'no date booked';
}
function waitingOnCard(c, events, nowMs) {
  var f = c.fields || {};
  if (c.status !== 'interview' || !f.interviewAt || daysLeft(f.interviewAt, nowMs) >= 0) return false;
  return !cardsFor(c, events).some(function (e) { return String(e.at).slice(0, 10) >= String(f.interviewAt); });
}
function candidateLine(c, events) {
  var f = c.fields || {};
  var avg = averages(c, events);
  var keys = Object.keys(avg);
  return (
    f.name + ' (' + c.id + ')' +
    (c.status === 'interview' ? ', interview ' + interviewText(c) : '') +
    (keys.length ? ', ratings ' + keys.map(function (k) { return k + ' ' + avg[k]; }).join(', ') : '')
  );
}
function picture(roles, candidates, events, nowMs, withinDays) {
  var live = roles.filter(function (r) { return r.status === 'open' || r.status === 'paused'; });
  var active = candidates.filter(function (c) { return c.status !== 'hired' && c.status !== 'closed'; });
  var titleOf = function (c) {
    var r = roles.filter(function (x) { return x.id === c.fields.roleId; })[0];
    return r ? r.fields.title : c.fields.roleTitle || 'a role';
  };
  var byDay = function (a, b) { return String(a.fields.interviewAt).localeCompare(String(b.fields.interviewAt)); };
  var soon = active
    .filter(function (c) {
      if (c.status !== 'interview' || !c.fields.interviewAt) return false;
      var d = daysLeft(c.fields.interviewAt, nowMs);
      return d >= 0 && d <= withinDays;
    })
    .sort(byDay);
  var waiting = active.filter(function (c) { return waitingOnCard(c, events, nowMs); }).sort(byDay);
  var parts = [];
  // The interview list comes first and whole: "who's interviewing this week" is answered from it alone.
  parts.push(
    soon.length
      ? 'Interviews in the next ' + withinDays + ' days: ' + soon.map(function (c) { return c.fields.name + ' (' + c.id + ') for ' + titleOf(c) + ' on ' + interviewText(c); }).join('; ') + '.'
      : 'No interviews booked in the next ' + withinDays + ' days.',
  );
  if (waiting.length) {
    parts.push('Interviewed but no scorecard yet: ' + waiting.map(function (c) { return c.fields.name + ' (' + c.id + ', ' + titleOf(c) + ', interviewed ' + c.fields.interviewAt + ')'; }).join('; ') + '.');
  }
  parts.push(live.length ? live.length + (live.length === 1 ? ' open role' : ' open roles') + ', ' + active.length + ' candidates in play.' : 'No open roles.');
  live.forEach(function (r) {
    var mine = candidates.filter(function (c) { return c.fields.roleId === r.id; });
    var hired = mine.filter(function (c) { return c.status === 'hired'; }).length;
    var stages = STAGES.slice(0, 4).map(function (s) {
      var list = mine.filter(function (c) { return c.status === s; });
      return s + ': ' + (list.length ? list.map(function (c) { return candidateLine(c, events); }).join('; ') : 'none');
    });
    parts.push(
      r.fields.title + ' (' + r.id + (r.status === 'paused' ? ', paused' : '') + ', ' + hired + ' of ' + (r.fields.openings || 1) + ' hired' +
        (r.fields.manager ? ', manager ' + r.fields.manager : '') +
        '; requirements: ' + ((r.fields.requirements || []).join(', ') || 'none written yet') + ') ' + stages.join(' | ') + '.',
    );
  });
  return { openRoles: live.length, inPipeline: active.length, interviewsSoon: soon.length, summary: parts.join(' ') };
}
// ── hiring-rules-end ──

const roles = rosterStore(gezel.fs, 'roles.json', { stages: ['open', 'paused', 'filled', 'closed'], idPrefix: 'role' });
const candidates = rosterStore(gezel.fs, 'candidates.json', {
  stages: ['sourced', 'screen', 'interview', 'offer', 'hired', 'closed'],
  idPrefix: 'cand',
});
const feedback = logStore(gezel.fs, 'feedback.json');
const now = Date.now();
const roleTitle = (r: { fields: Record<string, unknown> }) => String(r.fields.title ?? '');
const candName = (r: { fields: Record<string, unknown> }) => String(r.fields.name ?? '');

async function resolveRole(text?: string) {
  const all = await roles.list();
  if (!text) {
    const open = all.filter((r) => r.status === 'open');
    if (open.length === 1) return open[0]!;
    throw new Error("Pass 'role' (id or title). Roles: " + (describe(all, roleTitle) || 'none yet; open one with add_role') + '.');
  }
  const hits = matches(all, text, roleTitle);
  if (hits.length === 1) return hits[0]!;
  if (hits.length > 1) throw new Error("More than one role matches '" + text + "': " + describe(hits, roleTitle) + '. Pass the id.');
  throw new Error("No role matches '" + text + "'. Roles: " + (describe(all, roleTitle) || 'none yet; open one with add_role') + '.');
}

async function resolveCandidate(text?: string) {
  if (!text) throw new Error("Pass 'candidate': an id like 'cand-3' or a name. Call list_candidates to see them.");
  const all = await candidates.list();
  const active = all.filter((c) => c.status !== 'hired' && c.status !== 'closed');
  let hits = matches(active, text, candName);
  if (!hits.length) hits = matches(all, text, candName);
  if (hits.length === 1) return hits[0]!;
  if (hits.length > 1) throw new Error("More than one candidate matches '" + text + "': " + describe(hits, candName) + '. Pass the id.');
  throw new Error("No candidate matches '" + text + "'. Candidates: " + (describe(all, candName) || 'none yet') + '.');
}

const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 7;
let note = '';

if (input.action === 'add_role') {
  if (!input.title || !input.title.trim()) throw new Error("add_role needs 'title'.");
  const title = input.title.trim();
  const reqs = input.requirements === undefined ? [] : splitList(input.requirements);
  for (const text of [title, ...reqs]) {
    const term = protectedTerm(text);
    if (term) throw new Error(protectedMessage(term));
  }
  let openings: number | undefined;
  if (input.openings !== undefined) {
    openings = Math.round(Number(input.openings));
    if (!(openings >= 1)) throw new Error("openings must be 1 or more.");
  }
  const roleStatus = input.roleStatus ? String(input.roleStatus).trim().toLowerCase() : '';
  if (roleStatus && !ROLE_STATUSES.includes(roleStatus)) throw new Error("roleStatus must be open, paused, filled, or closed.");
  const fields: Record<string, unknown> = {
    ...(reqs.length ? { requirements: reqs } : {}),
    ...(openings ? { openings } : {}),
    ...(input.manager ? { manager: input.manager.trim() } : {}),
    ...(input.pay ? { pay: input.pay.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  const existing = (await roles.list()).find((r) => roleTitle(r).toLowerCase() === title.toLowerCase());
  if (existing) {
    await roles.update(existing.id, { fields });
    if (roleStatus && roleStatus !== existing.status) await roles.transition(existing.id, roleStatus);
    note = 'Updated the ' + roleTitle(existing) + ' role (' + existing.id + ').';
  } else {
    const record = await roles.add({
      status: roleStatus || 'open',
      fields: { title, requirements: [], openings: 1, openedAt: localDay(now), ...fields },
    });
    note = 'Opened ' + title + ' (' + record.id + ')' + (reqs.length ? ' with ' + reqs.length + ' requirements.' : '; add its job-related requirements next.');
  }
} else if (input.action === 'add_candidate') {
  if (!input.name || !input.name.trim()) throw new Error("add_candidate needs 'name'.");
  const name = input.name.trim();
  const role = await resolveRole(input.role);
  const interviewAt = input.interviewOn ? parseDay(input.interviewOn, now, 'future') : null;
  if (input.interviewOn && !interviewAt) throw new Error("interviewOn must be a date like '2026-11-12' or a weekday like 'thursday'.");
  // A booked interview puts a new candidate straight at the interview stage.
  const stage = input.status ? stageOf(input.status) : interviewAt ? 'interview' : '';
  if (stage && !STAGES.includes(stage)) throw new Error('status must be one of ' + STAGES.join(', ') + '.');
  const fields: Record<string, unknown> = {
    ...(input.source ? { source: input.source.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
    ...(interviewAt ? { interviewAt } : {}),
    ...(input.interviewTime ? { interviewTime: input.interviewTime.trim() } : {}),
    ...(input.interviewer ? { interviewer: input.interviewer.trim() } : {}),
  };
  const existing = (await candidates.list()).find((c) => candName(c).toLowerCase() === name.toLowerCase() && c.fields.roleId === role.id);
  let id = '';
  if (existing) {
    id = existing.id;
    await candidates.update(existing.id, { fields, ...(input.note ? { note: input.note } : {}) });
    if (stage && stage !== existing.status) await candidates.transition(existing.id, stage);
    note = 'Updated ' + name + ' (' + existing.id + ') for ' + roleTitle(role) + '.';
  } else {
    const record = await candidates.add({
      status: stage || 'sourced',
      fields: { name, roleId: role.id, roleTitle: roleTitle(role), ...fields },
      ...(input.note ? { note: input.note } : {}),
    });
    id = record.id;
    note = 'Added ' + name + ' (' + record.id + ') to ' + roleTitle(role) + ' at ' + record.status + '.';
  }
  if (interviewAt) {
    const after = (await candidates.get(id))!;
    await feedback.append({ kind: 'booked', note: 'Interview booked for ' + interviewText(after) + '.', data: { candidateId: id, roleId: role.id, on: interviewAt } });
    note += ' Interview ' + interviewText(after) + '.';
  }
} else if (input.action === 'move') {
  const cand = await resolveCandidate(input.candidate ?? input.name);
  let to = input.status ? stageOf(input.status) : '';
  const interviewAt = input.interviewOn ? parseDay(input.interviewOn, now, 'future') : null;
  if (input.interviewOn && !interviewAt) throw new Error("interviewOn must be a date like '2026-11-12' or a weekday like 'thursday'.");
  if (!to && interviewAt) to = 'interview';
  if (!to) throw new Error("move needs 'status' (" + STAGES.join(', ') + ") or 'interviewOn'.");
  if (!STAGES.includes(to)) throw new Error('status must be one of ' + STAGES.join(', ') + '.');
  const fields: Record<string, unknown> = {
    ...(interviewAt ? { interviewAt } : {}),
    ...(input.interviewTime ? { interviewTime: input.interviewTime.trim() } : {}),
    ...(input.interviewer ? { interviewer: input.interviewer.trim() } : {}),
  };
  if (Object.keys(fields).length) await candidates.update(cand.id, { fields });
  if (to !== cand.status) await candidates.transition(cand.id, to, input.note ? { note: input.note } : {});
  else if (input.note) await candidates.update(cand.id, { note: input.note });
  const after = (await candidates.get(cand.id))!;
  if (interviewAt) {
    await feedback.append({
      kind: 'booked',
      note: 'Interview booked for ' + interviewText(after) + '.',
      data: { candidateId: cand.id, roleId: cand.fields.roleId, on: interviewAt },
    });
  }
  note = candName(cand) + (to !== cand.status ? ' moved from ' + cand.status + ' to ' + to : ' stays at ' + to) + (to === 'interview' ? ', interview ' + interviewText(after) : '') + '.';
  if (to === 'hired') {
    const role = await roles.get(String(cand.fields.roleId));
    if (role) {
      const hired = (await candidates.list()).filter((c) => c.fields.roleId === role.id && c.status === 'hired').length;
      const openings = Number(role.fields.openings) || 1;
      if (hired >= openings && role.status === 'open') {
        await roles.transition(role.id, 'filled', { note: hired + ' of ' + openings + ' hired' });
        note += ' ' + roleTitle(role) + ' is now filled.';
      } else {
        note += ' ' + roleTitle(role) + ': ' + hired + ' of ' + openings + ' hired.';
      }
    }
  }
} else if (input.action === 'feedback') {
  const cand = await resolveCandidate(input.candidate ?? input.name);
  const role = await roles.get(String(cand.fields.roleId));
  const reqs = role && Array.isArray(role.fields.requirements) ? (role.fields.requirements as string[]) : [];
  const parsed = parseRatings(input.ratings, reqs);
  if (parsed.problems.length) throw new Error(parsed.problems.join('; ') + '. Rate each requirement from 1 (no evidence) to 4 (strong evidence).');
  const keys = Object.keys(parsed.ratings);
  if (!keys.length && !input.note && !input.ratings) throw new Error("feedback needs 'ratings' (e.g. '" + (reqs[0] || 'Customer service') + " 3') or a 'note'.");
  const by = input.by && input.by.trim() ? input.by.trim() : 'an interviewer';
  const text = input.note ? input.note.trim() : !keys.length && input.ratings ? input.ratings.trim() : undefined;
  await feedback.append({
    kind: keys.length ? 'scorecard' : 'note',
    ...(text ? { note: text } : {}),
    data: {
      candidateId: cand.id,
      roleId: cand.fields.roleId,
      by,
      ...(keys.length ? { ratings: parsed.ratings } : {}),
      ...(parsed.unmatched.length ? { unmatched: parsed.unmatched } : {}),
    },
  });
  note = keys.length
    ? 'Scorecard from ' + by + ' for ' + candName(cand) + ': ' + keys.map((k) => k + ' ' + parsed.ratings[k]).join(', ') + '.'
    : 'Note from ' + by + ' on ' + candName(cand) + ' saved.';
  if (!keys.length && input.ratings) note += ' No ratings found in that text; rate each requirement 1 to 4, e.g. ' + (reqs[0] || 'Customer service') + ' 3.';
  if (parsed.unmatched.length) note += ' Not among the role’s requirements: ' + parsed.unmatched.join(', ') + '.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, add_role, add_candidate, move, feedback, or list.");
}

const allRoles = await roles.list();
const allCandidates = await candidates.list();
const events = await feedback.list();
const view = picture(allRoles, allCandidates, events, now, withinDays);

gezel.output({
  openRoles: view.openRoles,
  inPipeline: view.inPipeline,
  interviewsSoon: view.interviewsSoon,
  summary:
    input.action === 'list'
      ? allCandidates
          .map((c) => {
            const role = allRoles.find((r) => r.id === c.fields.roleId);
            return '[' + c.status + '] ' + candidateLine(c, events) + ', ' + (role ? roleTitle(role) : String(c.fields.roleTitle ?? '')) + (c.fields.source ? ', from ' + String(c.fields.source) : '') + (c.fields.notes ? '; ' + String(c.fields.notes) : '');
          })
          .join('\n') || 'No candidates yet.'
      : (note ? note + ' ' : '') + view.summary,
});

